// Optional user-supplied narration follows story seconds. No reference voice is bundled.
export function createNarrationPlayer(AudioClass=globalThis.Audio){const audio=AudioClass?new AudioClass():null;let loaded=false,src='';if(audio)audio.preload='metadata';return {get source(){return src},get loaded(){return loaded},attach(data){if(!audio)return false;audio.pause();src=data;audio.src=data;loaded=true;return true;},sync(time,playing,params={},rate=1){if(!audio||!loaded)return;if(!params.refineEnabled||!params.refineNarrationTiming||!params.refineSoundEnabled||!playing||time<0||Number.isFinite(audio.duration)&&time>=audio.duration){audio.pause();return;}audio.volume=Math.max(0,Math.min(1,params.refineSoundGain??.5));audio.playbackRate=Math.max(.1,Math.min(4,rate));if(!audio.seeking&&Math.abs(audio.currentTime-time)>.12)audio.currentTime=time;if(audio.paused)audio.play().catch(()=>{});},stop(){audio?.pause();}};}
export function narrationStore(indexedDB=globalThis.indexedDB){async function db(){if(!indexedDB)return null;return new Promise((resolve,reject)=>{const r=indexedDB.open('regaarder-narration-v71',1);r.onupgradeneeded=()=>r.result.createObjectStore('tracks');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}return {async load(){const d=await db();if(!d)return null;return new Promise((resolve,reject)=>{const t=d.transaction('tracks','readonly'),r=t.objectStore('tracks').get('active');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error);t.oncomplete=()=>d.close()})},async save(data){const d=await db();if(!d)throw Error('Audio storage unavailable');return new Promise((resolve,reject)=>{const t=d.transaction('tracks','readwrite'),s=t.objectStore('tracks'),r=s.get('active');r.onsuccess=()=>{if(r.result)s.put(r.result,'archive-'+Date.now());s.put(data,'active')};t.oncomplete=()=>{d.close();resolve()};t.onerror=()=>{d.close();reject(t.error)}})}};}
